#
# Signal errors, warnings and messages following the conventions for
# messages in functions that other packages call:
#
# - Exported functions that take `call` (and argument-name arguments
#   such as `x_arg`) register them on entry with `local_caller()`.
#   Helpers then name arguments with `arg_nm()`, and the function with
#   `user_frame()`. Only the outermost registering function of the
#   package counts, so when one exported function calls another,
#   messages refer to the function the user called.
# - Registration records whether the call is direct (`call` left at
#   its default) or another function supplied `call`.
# - `abort_msg()`, `warn_msg()` and `inform_msg()` wrap cli's signals
#   and drop hints (bullets named "i") unless the call is direct, since
#   hints name this package's own functions and arguments, which may
#   mean nothing to the user of a calling package.
#
# Every copy has its own registry, so each package registers
# independently of the others.
#
# Usage, in an exported function:
#
#   f <- function(x, x_arg = "x", call = rlang::current_env()) {
#     local_caller(args = list(x = x_arg), call = call)
#     ...
#     abort_msg(c("{.arg {arg_nm(\"x\")}} has length 0.",
#                 i = "Supply a value?"),
#               call = user_frame())
#   }
#
# ## Changelog
#
# 2026-11-27:
# - First version, from agetime (R/caller.R and `user_frame()` in
#   R/label-input.R), unchanged in behaviour. The registry is renamed
#   from `caller_env` to `msg_registry`, to avoid shadowing
#   `rlang::caller_env()`.
#
# nocov start


msg_registry <- new.env(parent = emptyenv())
msg_registry$active <- FALSE


#' Register Argument Names and Calling Function
#'
#' Registers names of arguments and the environment of the function
#' to name in messages, for the duration of the calling function, and
#' whether the call is direct (`call` is the calling function's own
#' frame). Does nothing if an outer function of this package has
#' already registered.
#'
#' @param args Named list. Names are the formal arguments
#' (eg `"labels"`), and values are the names to use in messages.
#' @param call Environment of the function to name in messages.
#' @param frame Frame of the function doing the registering.
#' @returns `TRUE` if registered, otherwise `FALSE`, invisibly.
#'
#' @noRd
local_caller <- function(args, call, frame = parent.frame()) {
  if (isTRUE(msg_registry$active)) {
    return(invisible(FALSE))
  }
  is_valid_arg <- function(x) is.character(x) && length(x) == 1L && !is.na(x)
  for (nm in names(args)) {
    if (!is_valid_arg(args[[nm]])) {
      abort_msg("{.arg {nm}} is not a single string.", call = call)
    }
  }
  if (!is.environment(call)) {
    abort_msg("{.arg call} is not an environment.", call = frame)
  }
  msg_registry$active <- TRUE
  msg_registry$args <- args
  msg_registry$call <- call
  msg_registry$direct <- identical(call, frame)
  do.call(base::on.exit,
          list(as.call(list(clear_caller)), add = TRUE, after = FALSE),
          envir = frame)
  invisible(TRUE)
}


#' Clear Registered Argument Names and Calling Function
#'
#' @returns `NULL`, invisibly.
#'
#' @noRd
clear_caller <- function() {
  msg_registry$active <- FALSE
  msg_registry$args <- NULL
  msg_registry$call <- NULL
  msg_registry$direct <- NULL
  invisible(NULL)
}


#' Name of an Argument, for Use in Messages
#'
#' @param nm Name of the formal argument, eg `"labels"`.
#' @returns The name registered by the user-facing function,
#' or `nm` if none was registered.
#'
#' @noRd
arg_nm <- function(nm) {
  ans <- if (isTRUE(msg_registry$active)) msg_registry$args[[nm]] else NULL
  if (is.null(ans)) nm else ans
}


#' Frame of the Function to Name in Messages
#'
#' The registered `call` if a function has registered; otherwise the
#' frame of the outermost function of this package on the call stack.
#'
#' @returns An environment.
#'
#' @noRd
user_frame <- function() {
  if (isTRUE(msg_registry$active)) {
    return(msg_registry$call)
  }
  ns <- topenv(environment(user_frame))
  n <- sys.nframe()
  for (i in seq_len(n - 1L)) {
    env_fun <- environment(sys.function(i))
    if (is.environment(env_fun) && identical(topenv(env_fun), ns)) {
      return(sys.frame(i))
    }
  }
  parent.frame()
}


#' Is the Current Call Direct?
#'
#' @returns `TRUE` if the registered function was called with `call`
#' left at its default, or if no function has registered (internal
#' use); `FALSE` if another function supplied `call`.
#'
#' @noRd
is_direct_call <- function() {
  if (!isTRUE(msg_registry$active)) {
    return(TRUE)
  }
  isTRUE(msg_registry$direct)
}


#' Drop Hints from a Message, Unless the Call Is Direct
#'
#' Hints are bullets named `"i"`: advice that names this package's own
#' functions or arguments, which may mean nothing to the user of a
#' calling package.
#'
#' @param message Character vector of message bullets.
#' @returns `message`, without bullets named `"i"` if the call
#' is not direct.
#'
#' @noRd
drop_hints <- function(message) {
  nms <- names(message)
  if (is.null(nms) || is_direct_call()) {
    return(message)
  }
  message[nms != "i"]
}


#' Signal Errors, Warnings and Messages
#'
#' Wrappers around [cli::cli_abort()], [cli::cli_warn()] and
#' [cli::cli_inform()] that drop hints when the call is not direct.
#' All of the package's messages go through these.
#'
#' @param message Character vector of message bullets.
#' @param ... Passed to the cli function.
#' @param call Environment of the function to name in the error.
#' @param .envir Environment in which to interpolate `message`.
#'
#' @noRd
abort_msg <- function(message, ..., call = .envir, .envir = parent.frame()) {
  cli::cli_abort(drop_hints(message), ..., call = call, .envir = .envir)
}

#' @rdname abort_msg
#' @noRd
warn_msg <- function(message, ..., .envir = parent.frame()) {
  cli::cli_warn(drop_hints(message), ..., .envir = .envir)
}

#' @rdname abort_msg
#' @noRd
inform_msg <- function(message, ..., .envir = parent.frame()) {
  cli::cli_inform(drop_hints(message), ..., .envir = .envir)
}


# nocov end
